            credential_id?: string | null;
            /**
             * Brand
             * @description Card brand, for example `visa`.
             */
            brand?: string | null;
            /**
             * Last4
             * @description Last four digits.
             */
            last4?: string | null;
            /**
             * Exp Month
             * @description Expiry month.
             */
